14	public class EnsureCityCapacity {
15	
16	    /** Maximum number of owners a single city may hold. */
17	    static final int CAPACITY = 50;
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws CityAtCapacityException {
21	        String city = request.getCity();
22	        long existing = ownerRepository.findAll().stream()
23	                .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
24	                .count();
25	        if (existing >= CAPACITY) {
26	            throw new CityAtCapacityException(city, CAPACITY);
27	        }
28	    }
29	}
